from pathlib import Path
import json
ROOT=Path('/workspace/scratch/396f0b68d07d/comparison-assessments/J1')
MAN=json.loads((ROOT/'manifest.json').read_text())
OUT=ROOT/'assessment.json'
def add(label,statuses,evidences,notes=None):
 d=json.loads(OUT.read_text()); entry=MAN['packets'][len(d['runs'])]
 assert entry['label']==label,(entry,label)
 req=json.loads((Path(entry['packet'])/'requirements.json').read_text())['requirements']
 assert len(statuses)==len(evidences)==len(req)
 assert set(statuses)<= {'met','refuted','not_verified'}
 r={'label':label,'case_id':entry['case_id'],'requirements':[{'id':a['id'],'status':s,'evidence':e} for a,s,e in zip(req,statuses,evidences)]}
 if notes:r['notes']=notes
 d['runs'].append(r); OUT.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 print('Saved',label,';',len(d['runs']),'/',len(MAN['packets']))
def clean(x):
 if isinstance(x,dict):
  return {k:clean(v) for k,v in x.items() if k not in {'command','runner_output','checker_sha256','observed_at_utc'} and not (k in {'stdout','stderr','subject_output'} and not v)}
 if isinstance(x,list):
  if len(x)>12:return {'list_length':len(x),'first_two':[clean(v) for v in x[:2]],'last_two':[clean(v) for v in x[-2:]]}
  return [clean(v) for v in x]
 return x
def show(label):
 p=Path(next(x['packet'] for x in MAN['packets'] if x['label']==label))
 for name in ['task.json','requirements.json']:
  print('\nFILE',label+'/'+name); print((p/name).read_text())
 for f in sorted((p/'source').rglob('*')):
  if f.is_file():
   print('\nSOURCE',f.relative_to(p/'source')); print(f.read_text())
 for f in sorted((p/'work').rglob('*')):
  if f.is_file():
   orig=p/'source'/f.relative_to(p/'work')
   if orig.is_file() and orig.read_bytes()==f.read_bytes():
    print('\nWORK',f.relative_to(p/'work'),'[identical to source]')
   else:
    print('\nWORK',f.relative_to(p/'work')); print(json.dumps(clean(json.loads(f.read_text())),ensure_ascii=False) if f.suffix=='.json' else f.read_text())
 for f in sorted(p.iterdir()):
  if f.is_file() and f.name not in {'task.json','requirements.json'}:
   print('\nFILE',label+'/'+f.name)
   if f.suffix=='.json': print(json.dumps(clean(json.loads(f.read_text())),ensure_ascii=False))
   else:print(f.read_text())

