"""Build treatment-blinded assessment copies after all subject captures exist."""
import hashlib,json,random,shutil
from pathlib import Path

ROOT=Path('/workspace/scratch/396f0b68d07d')
EVALS=ROOT/'assay/skills/skill-evaluation/evals'
CASE={x['id']:x for x in json.loads((EVALS/'comparison-cases.json').read_text())['cases']}
RUBRIC={x['id']:x for x in json.loads((EVALS/'comparison-rubric.json').read_text())['cases']}
PLAN=json.loads((ROOT/'comparison-runtime/runtime-plan.json').read_text())
TARGET=ROOT/'comparison-assessments'

def sha(data):return hashlib.sha256(data).hexdigest()

def prepare():
    missing=[r['run_id'] for r in PLAN if not (ROOT/'comparison-capture'/r['run_id']/'capture.json').is_file()]
    if missing:raise ValueError('Unfinished captures: '+','.join(missing))
    if TARGET.exists():raise ValueError('Do not silently rewrite assessment packets')
    calibration_path=ROOT/'semantic-calibration/calibration.json'
    calibration=json.loads(calibration_path.read_text())
    controls=calibration['controls']
    if len(controls)!=4 or len({c['id'] for c in controls})!=4:
        raise ValueError('Expected the four independently frozen semantic controls')
    run_order=[{**r,'kind':'subject'} for r in PLAN]
    run_order.extend({'run_id':c['id'],'case_id':calibration['case_id'],'kind':'calibration','control':c} for c in controls)
    random.Random(2026100901).shuffle(run_order)
    mapping={f'K{i:02d}':r['run_id'] for i,r in enumerate(run_order,1)}
    packets=[]
    TARGET.mkdir()
    for i,row in enumerate(run_order,1):
        label=f'K{i:02d}';run=row['run_id'];packet=TARGET/'packets'/label
        packet.mkdir(parents=True)
        case=CASE[row['case_id']]
        (packet/'task.json').write_text(json.dumps({k:v for k,v in case.items() if k!='files'},ensure_ascii=False,indent=2)+'\n')
        (packet/'requirements.json').write_text(json.dumps(RUBRIC[row['case_id']],ensure_ascii=False,indent=2)+'\n')
        source=packet/'source';source.mkdir()
        for name,text in case['files'].items():
            p=source/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(text.encode('utf-8'))
        if row['kind']=='subject':
            capture=ROOT/'comparison-capture'/run
            shutil.copytree(capture/'work',packet/'work')
            observed=json.loads((capture/'capture.json').read_text())
        else:
            work=packet/'work';shutil.copytree(source,work)
            for name,content in row['control']['files'].items():
                if name!='answer.md':raise ValueError('Semantic controls may only add their constructed answer')
                (work/name).write_bytes(content.encode('utf-8'))
            original={name:sha(content.encode('utf-8')) for name,content in case['files'].items()}
            output={p.relative_to(work).as_posix():sha(p.read_bytes()) for p in sorted(work.rglob('*')) if p.is_file()}
            observed={'source_files':original,'output_files':output,'changed_source_files':[],
                      'new_files':['answer.md'],
                      'trace_limit':'Final retained bytes and worker reports; no exported host trajectory or proof of no transient writes/outside reads.'}
        (packet/'final_inventory.json').write_text(json.dumps({k:v for k,v in observed.items() if k in {'source_files','output_files','changed_source_files','new_files','trace_limit'}},indent=2)+'\n')
        check=ROOT/'comparison-deterministic-v2'/(run+'.json')
        if check.exists():
            result=json.loads(check.read_text())
            # Share observations, not another grader's criterion statuses.
            evidence={'case':row['case_id'],'evidence':result['evidence'],
                      'evaluator_preserved_subject_bytes':result['evaluator_preserved_subject_bytes'],
                      'limits':result['limits'], 'checker_sha256':result['checker_sha256'],
                      'observed_at_utc':result['observed_at_utc']}
            (packet/'coordinator_behavior.json').write_text(json.dumps(evidence,ensure_ascii=False,indent=2)+'\n')
        packets.append({'label':label,'case_id':row['case_id'],'packet':str(packet)})
    instructions=(ROOT/'comparison-assessment-instructions.txt').read_bytes()
    order=list(packets);random.Random(2026100902).shuffle(order)
    identities={}
    for number,rows in [(1,order),(2,list(reversed(order)))]:
        name=f'J{number}';folder=TARGET/name;folder.mkdir()
        (folder/'instructions.txt').write_bytes(instructions)
        manifest={'assessment_id':name,'packets':rows,'output':str(folder/'assessment.json'),
                  'scope':'Grade every artifact independently against the original contract; treatment mapping and other assessments withheld'}
        (folder/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
        identities[name]={'manifest_sha256':sha((folder/'manifest.json').read_bytes()),'instruction_sha256':sha(instructions),'order':[r['label'] for r in rows]}
    packet_digests={}
    for packet in packets:
        folder=Path(packet['packet'])
        packet_digests[packet['label']]={p.relative_to(folder).as_posix():sha(p.read_bytes()) for p in sorted(folder.rglob('*')) if p.is_file()}
    record={'label_randomization_seed':2026100901,'order_randomization_seed':2026100902,
            'mapping':mapping,'assessments':identities,'packet_digests':packet_digests,
            'subject_run_ids':[r['run_id'] for r in PLAN],
            'calibration_control_ids':[c['id'] for c in controls],
            'calibration_sha256':sha(calibration_path.read_bytes()),
            'calibration_boundary':'Four constructed grading controls, frozen before assessment, are excluded from the 42 subject executions and their performance denominators.',
            'blinding_limit':'Instruction-only access boundary; output content can reveal skill names or literal run paths. Shared filesystem is not protected exclusion.'}
    (ROOT/'comparison-assessment-map.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'packets':len(packets),'subject_outputs':len(PLAN),'constructed_controls':len(controls),'assessments':list(identities),'root':str(TARGET)}))

if __name__=='__main__':prepare()

