    mapping=read(ROOT/'comparison-assessment-map.json')
    calibration=read(ROOT/'semantic-calibration/calibration.json')
    if digest((ROOT/'semantic-calibration/calibration.json').read_bytes())!=mapping['calibration_sha256']:
        raise ValueError('Frozen calibration changed')
    assessments={}
    for name in mapping['assessments']:
        raw=read(ASSESS/name/'assessment.json')
        if raw['assessment_id']!=name:raise ValueError('Wrong assessment identity')
        rows=report.keyed(raw['runs'],'label')
        if set(rows)!=set(mapping['mapping']):raise ValueError('Assessment is incomplete')
        assessments[name]=rows
    for label,expected in mapping['packet_digests'].items():
        packet=ASSESS/'packets'/label
        actual={p.relative_to(packet).as_posix():digest(p.read_bytes()) for p in sorted(packet.rglob('*')) if p.is_file()}
        if actual!=expected:raise ValueError('Blinded packet changed: '+label)
    return plan,evidence,rubric,cases,mapping,calibration,assessments


def inspect():
    plan,evidence,rubric,cases,mapping,calibration,assessments=inputs()
    stats=report.assessment_statistics(mapping,calibration,assessments)
    inverse={identity:label for label,identity in mapping['mapping'].items()}
    detail=[]
    for disagreement in stats['subjects']['disagreements']:
        label=inverse[disagreement['run_id']]
        detail.append({**disagreement,'label':label,'judgments':{
            name:report.keyed(rows[label]['requirements'],'id')[disagreement['criterion_id']]
            for name,rows in assessments.items()}})
    target=ROOT/'comparison-assessment-inspection.json'
    target.write_text(json.dumps({'statistics':stats,'disagreement_details':detail},ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'file':str(target),'subject_requirements':stats['subjects']['requirements'],
                      'agreement':stats['subjects']['matching_statuses'],
                      'disagreements':len(detail),'calibration':stats['calibration']},ensure_ascii=False))


def assemble():
    plan,evidence,rubric,cases,mapping,calibration,assessments=inputs()
    events=read(ROOT/'comparison-assessment-events.json')
    if {r['assessment_id'] for r in events if r['event']=='completion_observed'}!=set(assessments):
        raise ValueError('Wait for both actual assessment completions')
    extra={}
    def retain(path):
        data=Path(path).read_bytes();sha=digest(data);text=data.decode('utf-8')
        assert text.encode('utf-8')==data
        if sha not in evidence['blobs']:extra[sha]=text
        return sha
    mapping_sha=retain(ROOT/'comparison-assessment-map.json')
    calibration_sha=retain(ROOT/'semantic-calibration/calibration.json')
    for label,files in mapping['packet_digests'].items():
        for name,sha in files.items():
            if retain(ASSESS/'packets'/label/name)!=sha:raise ValueError('Packet digest mismatch')
    supporting={}
    for name in ['assessment-adjudication-review.json','comparison-adjudications.json']:
        supporting['adjudication/'+name]=retain(ROOT/name)
    for path in sorted((ROOT/'semantic-calibration').rglob('*')):
        if path.is_file():supporting['semantic-calibration/'+path.relative_to(ROOT/'semantic-calibration').as_posix()]=retain(path)
    records=[]
    for name in sorted(assessments):
        folder=ASSESS/name
        files={p.relative_to(folder).as_posix():retain(p) for p in sorted(folder.rglob('*')) if p.is_file() and '__pycache__' not in p.parts}
        message=(f'Read /workspace/scratch/396f0b68d07d/comparison-assessments/{name}/instructions.txt and /workspace/scratch/396f0b68d07d/comparison-assessments/{name}/manifest.json. '
                 f'Assess every listed packet in manifest order under those instructions and write the requested assessment.json in the assigned {name} directory. '
                 'Use only the permitted packet files and your own assessment directory; do not read source checkouts, trial launch instructions, mappings, method files or other assessments. '
                 'Do not execute submitted programs, access external services, change saved artifacts or spawn subagents. '
                 'Preserve initial judgments if correcting a format or factual error. Return the saved assessment path and actual unresolved issues.')
        records.append({'assessment_id':name,'task_name':'agent:assessment_'+name.lower(),
                        'requested_executor':{'model':'gpt-6-astra','reasoning_effort':'ultra','fork_turns':'none'},
                        'resolved_executor':{'model':None,'reasoning_effort':None,'version':None},
                        'host_message':message,
                        'host_message_retention':'Literal dispatched template instantiated for the observed call; retained after execution.',
                        'manifest_sha256':files['manifest.json'],'instruction_sha256':files['instructions.txt'],
                        'output_sha256':files['assessment.json'],'retained_files':files,
                        'api_tokens':None,'billed_cost':None,'provider_latency_seconds':None})
    decision_record=read(ROOT/'comparison-adjudications.json')
    decisions=decision_record['decisions']
    adjudicated={(d['run_id'],d['criterion_id']):d for d in decisions}
    if len(adjudicated)!=len(decisions):raise ValueError('Duplicate adjudication')
    inverse={identity:label for label,identity in mapping['mapping'].items()}
    required={case['id']:case['requirements'] for case in rubric['cases']}
    final=[]
    for trial in plan['trials']:
        run=trial['run_id'];label=inverse[run];requirements=[]
        original={name:report.keyed(rows[label]['requirements'],'id') for name,rows in assessments.items()}
        for criterion in required[trial['case_id']]:
            cid=criterion['id'];initial={name:rows[cid]['status'] for name,rows in original.items()}
            decision=adjudicated.get((run,cid))
            if decision:
                if decision['initial_statuses']!=initial:raise ValueError('Adjudication original statuses differ')
                status=decision['final_status'];reason=decision['rationale']
            else:
                if len(set(initial.values()))!=1:raise ValueError(f'Unresolved assessment disagreement: {run}/{cid}')
                status=next(iter(initial.values()))
                reason=' '.join(f'{name}: {rows[cid]["evidence"]}' for name,rows in original.items())
            requirements.append({'id':cid,'status':status,'evidence':reason})
        final.append({'run_id':run,'case_id':trial['case_id'],'arm':trial['arm'],'requirements':requirements})
    code={}
    for name in ['comparison_report.py','test_comparison_report.py']:
        code[name]=retain(EVALS/name)
    code['coordinator/assemble_grades.py']=retain(ROOT/'assemble_grades.py')
    receipt_policy={'run_ids':sorted(row['run_id'] for row in plan['trials'] if row['case_id'] in {'B1-M','B1-C','B4-C'}),
                    'checker_sha256_by_receipt_version':{
                        'v1_blob_sha256':next(row['blob_sha256'] for row in evidence['measurement_history'] if row['path']=='v1/comparison_checks.py'),
                        'v2_blob_sha256':evidence['implementation_blobs']['comparison_checks.py']}}
    result={'schema_version':1,'evidence_sha256':digest((EVALS/'comparison-evidence.json').read_bytes()),
            'rubric_sha256':digest((EVALS/'comparison-rubric.json').read_bytes()),
            'retained_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
            'assessment_provenance':{'mapping_sha256':mapping_sha,'calibration_sha256':calibration_sha,
                'preparation_sha256':retain(ROOT/'prepare_assessments.py'),'assessments':records,
                'supporting_files':supporting,'execution_events':events,'deterministic_policy':receipt_policy,
                'time_boundary':'Delayed coordinator observation times, not provider start/end or latency.',
                'calibration_boundary':'Four constructed B5-M controls were frozen before assessment by a separate fresh context allowed only the task, rubric and status instructions. They are excluded from the 42 subject executions.',
                'blinding_boundary':mapping['blinding_limit'],
                'judge_boundary':'Two requested same-family model configurations, not observed backend identities or human ground truth. Packet order is declared, not proven historical read order.'},
            'assessment_summary':report.assessment_statistics(mapping,calibration,assessments),
            'adjudication_policy':'Retain both raw judgments. Resolve each disagreement from the original contract and exact saved evidence, without majority-vote truth, new task criteria or subject reruns. Shared errors may also be corrected with an explicit original/final record.',
            'adjudications':decisions,'scope_sensitivity':decision_record['scope_sensitivity'],
            'calibration_scope_note':decision_record['calibration_scope_note'],
            'runs':final,'verification_implementation_blobs':code,
            'measurement_boundary':'The CSV checker v2 repaired a demonstrated false acceptance. All eight affected retained artifacts were rechecked; no criterion status changed and all four submitted B1-M suites passed. The task/rubric/source allocations stayed fixed. Later evidence-validation changes do not overwrite prior implementation bytes.',
            'blobs':dict(sorted(extra.items()))}
    report.verify(plan,evidence,result,rubric)
    report.verify_assessments(plan,evidence,result,rubric,cases)
    target=EVALS/'comparison-grades.json'
    if target.exists():raise ValueError('Final grade identity already exists; retain any revision separately')
    target.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'file':str(target),'sha256':digest(target.read_bytes()),'runs':len(final),
                      'extra_blobs':len(extra),'bytes':target.stat().st_size,
                      'adjudications':len(decisions)}))


if __name__=='__main__':
    if sys.argv[1:] == ['inspect']:inspect()
    elif sys.argv[1:] == ['assemble']:assemble()
    else:raise SystemExit('Use inspect or assemble')

